namespace Plugin.Boundary;

public sealed class PluginBoundary
{
    private readonly IPluginHost _host;

    public PluginBoundary(IPluginHost host)
    {
        _host = host;
    }

    public bool ValidatePayload(string payload)
    {
        if (string.IsNullOrWhiteSpace(payload)) return false;
        return payload.Length <= 4096;
    }

    public Task ForwardAsync(string payload, CancellationToken ct)
    {
        return _host.SendAsync(payload, ct);
    }
}

